{"sql":"-- Refine approach to getting average size of vector column: sample with a query per each vector column, then join results
-- Use PL/pgSQL block
DO $$
DECLARE
  rec RECORD;
  v_avg_size FLOAT;
  v_total_size BIGINT;
  v_rows BIGINT;
BEGIN
  DROP TABLE IF EXISTS vector_analysis_storage_consumption;
  CREATE TABLE vector_analysis_storage_consumption (
    schema VARCHAR(50),
    table_name VARCHAR(100),
    total_size_bytes BIGINT,
    vector_data_bytes BIGINT,
    regular_data_bytes BIGINT,
    vector_storage_pct NUMERIC(5,2),
    row_count BIGINT
  );

  FOR rec IN
    SELECT schema, table_name, column_name, rows
      FROM vector_analysis_columns
      ORDER BY schema, table_name
  LOOP
    EXECUTE FORMAT('SELECT AVG(pg_column_size(%I)) FROM %I.%I', rec.column_name, rec.schema, rec.table_name) INTO v_avg_size;
    IF v_avg_size IS NULL THEN
      v_avg_size := 0;
    END IF;

    v_total_size := ceil(v_avg_size * rec.rows);

    EXECUTE FORMAT('SELECT pg_total_relation_size(%L::regclass)', rec.schema || '.' || rec.table_name) INTO v_rows;

    INSERT INTO vector_analysis_storage_consumption VALUES (
      rec.schema, rec.table_name,
      (SELECT pg_total_relation_size(format('%I.%I', rec.schema, rec.table_name)::regclass),
      v_total_size,
      (SELECT pg_total_relation_size(format('%I.%I', rec.schema, rec.table_name)::regclass) - v_total_size),
      CASE WHEN (SELECT pg_total_relation_size(format('%I.%I', rec.schema, rec.table_name)::regclass) > 0) THEN
        (v_total_size::NUMERIC / (SELECT pg_total_relation_size(format('%I.%I', rec.schema, rec.table_name)::regclass))) * 100
      ELSE 0 END,
      rec.rows
    );
  END LOOP;
END $$;"}

