    regular_data_bytes BIGINT,
    vector_storage_pct NUMERIC(5,2),
    row_count BIGINT
  );

  FOR rec IN
    SELECT schema, table_name, column_name, rows
    FROM vector_analysis_columns
    ORDER BY schema, table_name
  LOOP
    EXECUTE FORMAT('SELECT AVG(pg_column_size(%I)) FROM %I.%I', rec.column_name, rec.schema, rec.table_name) INTO v_avg_size;
    IF v_avg_size IS NULL THEN
      v_avg_size := 0;
    END IF;

    v_total_size := CEIL(v_avg_size * rec.rows);

    EXECUTE FORMAT('SELECT pg_total_relation_size(%L::regclass)', rec.schema || '.' || rec.table_name) INTO v_total_table_size;

    INSERT INTO vector_analysis_storage_consumption VALUES (
      rec.schema, rec.table_name,
      v_total_table_size,
      v_total_size,
      v_total_table_size - v_total_size,
      CASE
        WHEN v_total_table_size > 0 THEN (v_total_size::NUMERIC / v_total_table_size) * 100
        ELSE 0
      END,
      rec.rows
   );
  END LOOP;
END $$;"}

{"sql":"-- Check for NULL vector embeddings and dimension mismatches per vector column
-- We need to do this per column due to SQL limitations; use dynamic SQL for each
DO $$
DECLARE
  rec RECORD;
  v_null_count BIGINT;
  v_mismatch_count BIGINT;
BEGIN
  RAISE NOTICE 'schema | table_name | column | null_count | dimension_mismatch';
  FOR rec IN SELECT schema, table_name, column_name, dimensions FROM vector_analysis_columns LOOP
    EXECUTE FORMAT(
      'SELECT COUNT(*) FILTER (WHERE %1$I IS NULL), COUNT(*) FILTER (WHERE array_length(%1$I::float4[], 1) != %2$L) FROM %3$I.%4$I',
      rec.column_name, rec.dimensions, rec.schema, rec.table_name
    ) INTO v_null_count, v_mismatch_count;

    RAISE NOTICE '% | % | % | % | %', rec.schema, rec.table_name, rec.column_name, v_null_count, v_mismatch_count;
  END LOOP;
END $$;"}

{"sql":"-- Check for outliers in vectors using approximate length (Euclidean norm) in each vector column
DO $$
DECLARE
  rec RECORD;
  v_max FLOAT;
  v_min FLOAT;
  v_avg FLOAT;
  v_stddev FLOAT;
BEGIN
  RAISE NOTICE 'schema | table_name | column | min_norm | max_norm | avg_norm | stddev_norm';
  FOR rec IN SELECT schema, table_name, column_name FROM vector_analysis_columns LOOP
    EXECUTE FORMAT(
      'SELECT MIN(sqrt(sum(pow(elem, 2)))), MAX(sqrt(sum(pow(elem, 2)))), AVG(sqrt(sum(pow(elem, 2)))), STDDEV_SAMP(sqrt(sum(pow(elem, 2)))) FROM (SELECT unnest(%1$I::float4[]) AS elem FROM %2$I.%3$I) AS sub',
      rec.column_name, rec.schema, rec.table_name
    ) INTO v_min, v_max, v_avg, v_stddev;

    RAISE NOTICE '% | % | % | % | % | % | %', rec.schema, rec.table_name, rec.column_name, v_min, v_max, v_avg, v_stddev;
  END LOOP;
END $$;"}

{"sql":"-- Calculate vector norms for each vector as sqrt(sum of squares of vector elements), then aggregate stats
DO $$
DECLARE
  rec RECORD;
  v_min FLOAT;
  v_max FLOAT;
  v_avg FLOAT;
  v_stddev FLOAT;
BEGIN
  RAISE NOTICE 'schema | table_name | column | min_norm | max_norm | avg_norm | stddev_norm';
  FOR rec IN SELECT schema, table_name, column_name FROM vector_analysis_columns LOOP
    EXECUTE FORMAT(
      'SELECT MIN(norm), MAX(norm), AVG(norm), STDDEV_SAMP(norm) FROM (SELECT sqrt(sum(pow(elem, 2))) AS norm FROM (SELECT unnest(%I::float4[]) AS elem FROM %I.%I) AS elems GROUP BY 1) AS norms',
      rec.column_name, rec.schema, rec.table_name
    ) INTO v_min, v_max, v_avg, v_stddev;

    RAISE NOTICE '% | % | % | % | % | % | %', rec.schema, rec.table_name, rec.column_name, v_min, v_max, v_avg, v_stddev;
  END LOOP;
END $$;"}

