{"sql":"-- Manually calculate norms per vector row and aggregate without Group By using ROW_NUMBER
DO $$
DECLARE
  rec RECORD;
  v_min FLOAT;
  v_max FLOAT;
  v_avg FLOAT;
  v_stddev FLOAT;
BEGIN
  RAISE NOTICE 'schema | table_name | column | min_norm | max_norm | avg_norm | stddev_norm';
  FOR rec IN SELECT schema, table_name, column_name FROM vector_analysis_columns LOOP
    EXECUTE FORMAT(
      'WITH norms AS (
         SELECT sqrt(SUM(pow(elem, 2))) AS norm FROM (SELECT unnest(%I::float4[]) AS elem FROM %I.%I) unnested GROUP BY ROW_NUMBER() OVER ()
       )
       SELECT MIN(norm), MAX(norm), AVG(norm), STDDEV_SAMP(norm) FROM norms',
      rec.column_name, rec.schema, rec.table_name
    ) INTO v_min, v_max, v_avg, v_stddev;

    RAISE NOTICE '% | % | % | % | % | % | %', rec.schema, rec.table_name, rec.column_name, v_min, v_max, v_avg, v_stddev;
  END LOOP;
END $$;"}

{"sql":"-- Calculate vector norms row-wise without window functions by using generate_series for row number
DO $$
DECLARE
  rec RECORD;
  v_min FLOAT;
  v_max FLOAT;
  v_avg FLOAT;
  v_stddev FLOAT;
BEGIN
  RAISE NOTICE 'schema | table_name | column | min_norm | max_norm | avg_norm | stddev_norm';
  FOR rec IN SELECT schema, table_name, column_name FROM vector_analysis_columns LOOP
    EXECUTE FORMAT(
      'WITH vecs AS (SELECT %1$I FROM %2$I.%3$I),
        norms AS (
          SELECT sqrt(sum(pow(elem, 2))) AS norm FROM (
            SELECT unnest(vecs.%1$I::float4[]) AS elem FROM generate_series(1, (SELECT count(*) FROM %2$I.%3$I)) gs
          ) sub
        )
       SELECT MIN(norm), MAX(norm), AVG(norm), STDDEV_SAMP(norm) FROM norms',
      rec.column_name, rec.schema, rec.table_name
    ) INTO v_min, v_max, v_avg, v_stddev;

    RAISE NOTICE '% | % | % | % | % | % | %', rec.schema, rec.table_name, rec.column_name, v_min, v_max, v_avg, v_stddev;
  END LOOP;
END $$;"}
